<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount } from 'vue'; import type { Entity } from '@zhijiao/shared'; import { client, generation, isCurrent } from '../state'; import { titleOf, dateLabel } from '../format'; import Drawer from './Drawer.vue';
const props = defineProps<{ record: Entity }>(); const emit = defineEmits<{ close: []; restored: []; failure: [message: string] }>();
const versions = ref<Array<{ revision: string; tombstone: boolean; entity?: Entity }>>([]); const busy = ref(false); const loading = ref(true); const error = ref(''); const preview = ref<string>(); let active = true;
onMounted(async () => { const token = generation; try { const result = await client.value!.history(props.record.id); if (active && isCurrent(token)) versions.value = result; } catch { if (active && isCurrent(token)) error.value = '历史暂时无法加载，请连接网络后重试。'; } finally { if (active && isCurrent(token)) loading.value = false; } });
onBeforeUnmount(() => { active = false; versions.value = []; });
async function restore(revision: string) { if (busy.value) return; busy.value = true; const token = generation; try { await client.value!.restore(props.record.id, revision); if (active && isCurrent(token)) emit('restored'); } catch { if (active && isCurrent(token)) error.value = '恢复未完成，可能存在新版本。请同步并查看冲突。'; } finally { if (active && isCurrent(token)) busy.value = false; } }
</script>
<template><Drawer title="历史版本" :subtitle="titleOf(record)" :busy="busy" @close="emit('close')"><p class="notice">恢复会保存为一个新版本，不会清空后续历史。已删除记录的旧版本也可恢复。</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="muted">正在读取并在本机解密历史…</p><div v-for="version in versions" :key="version.revision" class="version-card"><div class="section-title"><strong>版本 {{ version.revision }} {{ version.tombstone ? ' · 已删除' : '' }}</strong><small>{{ version.entity ? dateLabel(version.entity.updatedAt) : '' }}</small></div><p v-if="version.entity" class="clamp">{{ titleOf(version.entity) }}</p><button v-if="version.entity" class="text-button" @click="preview = preview === version.revision ? undefined : version.revision">{{ preview === version.revision ? '收起详情' : '预览内容' }}</button><pre v-if="preview === version.revision && version.entity" class="history-preview">{{ JSON.stringify(version.entity, null, 2) }}</pre><button v-if="version.entity && !version.tombstone" class="button secondary" :disabled="busy" @click="restore(version.revision)">{{ busy ? '正在恢复…' : '将此版恢复为新版本' }}</button></div><p v-if="!loading && !versions.length" class="muted">还没有可读取的历史版本。</p></Drawer></template>
